def genericSelectionMajorant (d cutoff : Nat) (hd : 5 ≤ d) (n : Nat) : Nat :=
  GroupSelectionRecurrence.majorant d (genericSelectionBase d cutoff)
    (tollCoefficient d) 7 hd n

